<template>
  <div class="tel-compositor">
    <!-- <title-line :title="title" /> -->
    <div class="title">
      <div class="img" />
      <div>财富榜周排行</div>
    </div>
    <div class="time">
      <div>{{ time1 }}</div> <div style="color:rgba(16,16,16,1);padding:0 4px">至</div><div>{{ time2 }}</div>
    </div>
    <div class="compositor-table">
      <div class="first-line"><div class="item">名次</div><div class="item">用户名</div><div class="item">金额</div><div class="item">等级</div></div>
      <div class="list">
        <div v-for="(item,index) in datalist" :key="index" class="line-item" :style="index%2===0?'background:#fff':''">
          <div class="item">
            <div :class="index===0?'num1 item':index===1?'num2 item':index===2?'num3 item':'item'" />
            {{ index>2?item.num:'' }}
          </div>
          <div :class="index===0?'name1 item':index===1?'name2 item':index===2?'name3 item':'item'">{{ item.name }}</div>
          <div class="item">
            <div :class="index===0?'mons1':index===1?'mons2':index===2?'mons3':''">{{ item.mons }}</div>
          <!-- <div>{{ item.mons }}</div> -->
          </div>
          <div class="item" style="display:flex;justify-content: center;">
            <!-- <div :class="index===0?'rank1 item':index===1?'rank2 item':index===2?'rank3 item':'item'" /> -->
            {{ item.rank }}
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
// import TitleLine from '../modules/TitleLine'
import moment from 'moment'
import 'moment/locale/zh-cn'
moment.locale('zh-cn')
export default {
  components: {
    // TitleLine
  },
  data() {
    return {
      title: '财富榜',
      time1: '',
      time2: '',
      datalist: [
        // { num: 1, name: '张一三', mons: '562', rank: '41' },
        // { num: 1, name: '张一三', mons: '562', rank: '35' },
        // { num: 1, name: '张一三', mons: '562', rank: '30' },
        // { num: 1, name: '张一三', mons: '562' },
        // { num: 1, name: '张一三', mons: '562' },
        // { num: 1, name: '张一三', mons: '562' },
        // { num: 1, name: '张一三', mons: '562' },
        // { num: 1, name: '张一三', mons: '562' },
        // { num: 1, name: '张一三', mons: '562' },
        // { num: 1, name: '张一三', mons: '562' },
        // { num: 1, name: '张一三', mons: '562' }
      ]
    }
  },
  mounted() {
    const params = {}
    params.timef = moment().startOf('week').format('YYYYMMDDhhmmss')
    params.timet = moment().endOf('week').format('YYYYMMDDhhmmss')
    this.time1 = moment().startOf('week').format('YYYY-MM-DD')
    this.time2 = moment().endOf('week').format('YYYY-MM-DD')
    const paramsString = '?timef=' + params.timef + '&timet=' + params.timet + '&suid=' + this.$route.query.suid + '&pages=1&size=10'
    fetch(process.env.VUE_APP_BASE_API + '/yule/getBossRank' + paramsString, {
      method: 'GET'
    }).then(res => res.json())
      .then(data => {
        this.datalist = data.datalist.map((item, index) => {
          return {
            num: index + 1,
            name: item.username,
            mons: item.redpacksum,
            rank: item.viplevel
          }
        })
        // console.log(data)
        // this.userid = data.userid
        // this.chatid = data.chatid
      })
  },
  methods: {
  }

}
</script>
